import{_ as a,o as i,c as t,ak as n}from"./chunks/framework.B8jO0odJ.js";const p=JSON.parse('{"title":"Economy removal and simpler minigames","description":"Home · Decision map · Gameplay map","frontmatter":{"title":"Economy removal and simpler minigames","description":"Home · Decision map · Gameplay map","source":"docs/brain/decisions/economy-removal.md","category":"Other documents","sourceUpdated":"2026-11-11T12:24:37+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/brain/decisions/economy-removal.md","filePath":"content/docs/brain/decisions/economy-removal.md"}'),o={name:"content/docs/brain/decisions/economy-removal.md"};function s(r,e,d,c,l,h){return i(),t("div",null,[...e[0]||(e[0]=[n('<div><h1 id="economy-removal-and-simpler-minigames">Economy removal and simpler minigames<a class="header-anchor" href="#economy-removal-and-simpler-minigames" aria-label="Link to this section">​</a></h1><p><a href="/Chainy-Docs/content/docs/home.html">Home</a> · <a href="/Chainy-Docs/content/docs/brain/01-decisions.html">Decision map</a> · <a href="/Chainy-Docs/content/docs/brain/02-gameplay.html">Gameplay map</a></p><h2 id="what-the-earlier-discussion-establishes">What the earlier discussion establishes<a class="header-anchor" href="#what-the-earlier-discussion-establishes" aria-label="Link to this section">​</a></h2><p>The Codex chat titled <strong>Simplify GDD v2 scope</strong>, ID <code>01a16bf3-4c7d-7540-9d2b-672c48234e08</code>, contains the user&#39;s request to simplify V2 because the economy and additional mechanics were too complicated for the deadline. The requested teaching focus was Web3, blockchain, and AI fundamentals, with complicated mechanics redeveloped later. That chat was retrieved and read during the preceding search in this conversation.</p><p>The assistant recommended keeping exploration, guides, and restoration while using one reusable scenario-and-choice screen. The saved <a href="/Chainy-Docs/content/docs/planning/gdd-v2-simplification-review.html">simplification review</a> describes six encounters with fixed lesson examples instead of a functioning economy. That discussion ended with unresolved questions about shared scenarios, scripted AI examples, and confirmed development capacity.</p><h2 id="related-simplified-draft">Related simplified draft<a class="header-anchor" href="#related-simplified-draft" aria-label="Link to this section">​</a></h2><p>The separate <a href="/Chainy-Docs/content/docs/game-design-simplified-draft.html">simplified GDD draft</a> proposes:</p><table><thead><tr><th>Subject</th><th>Minigame</th></tr></thead><tbody><tr><td>Web3</td><td>Safe or Unsafe</td></tr><tr><td>Blockchain</td><td>Build the Chain</td></tr><tr><td>AI</td><td>Teach and Check the Bot</td></tr></tbody></table><p>It replaces coins, shops, inventory, and equipment with badges and sequential world unlocking. The file explicitly says it is a proposed replacement pending owner approval. The retrieved chat does not establish the origin or approval of this separate three-minigame draft.</p><h2 id="november-11-replacement-direction">November 11 replacement direction<a class="header-anchor" href="#november-11-replacement-direction" aria-label="Link to this section">​</a></h2><p>The owner subsequently specified exploration, tutorial NPCs, 13 ordered lessons per world, collectible encyclopedia entries, and distinct minigame scenes. The owner confirmed three minigames per world, sequential world unlocking, required quizzes, prerequisite-based teaching order, and offline AI simulations. The <a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html">lesson-collection GDD</a> now documents that direction and the <a href="/Chainy-Docs/content/docs/project-baseline.html">baseline</a> records its authority. The old economy GDD and alternative proposals remain historical.</p><p>The owner explicitly limited current work to documentation and necessary preparation; final approval is required before Unity development. Use the <a href="/Chainy-Docs/content/docs/planning/lesson-collection-delivery.html">readiness plan</a> for remaining review and future implementation gates. Keep the review and previous design as dated history. Sherwin owns the design decision; Sean authors the resulting documentation, with technical/UI/art handoffs to their named owners.</p></div>',1)])])}const f=a(o,[["render",s]]);export{p as __pageData,f as default};
